<?php
declare(strict_types=1);
require_once __DIR__ . '/business/config/role_mfa.php';
require_once __DIR__ . '/business/config/customer_membership.php';

$error=null;$csrf='';
try{
    $pdo=role_portal_db();role_mfa_ensure($pdo);cm_ensure($pdo);security_step17_session_start();
    if(role_mfa_pending_exists()){header('Location: mfa_verify.php');exit;}
    $existing=security_step17_session_user($pdo,false);
    if($existing){header('Location: '.((int)$existing['must_change_password']===1?'change_password.php?required=1':role_portal_home($existing)));exit;}
    $csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));
        $email=strtolower(trim((string)($_POST['email']??'')));$memberCode=strtoupper(trim((string)($_POST['member_code']??'')));
        if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$memberCode==='')throw new RuntimeException('Club Member sign-in details could not be verified.');
        $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];
        $s=$pdo->prepare("SELECT u.id FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? AND a.role_code='customer' AND a.is_active=1 JOIN customer_membership_profiles m ON m.organization_id=a.organization_id AND m.user_id=u.id AND m.membership_status='active' WHERE LOWER(u.email)=? AND UPPER(m.member_code)=? AND u.is_active=1 LIMIT 1");
        $s->execute([$orgId,$email,$memberCode]);$expectedUserId=(int)$s->fetchColumn();
        if($expectedUserId<=0)throw new RuntimeException('Club Member sign-in details could not be verified.');
        $user=role_mfa_login($pdo,$email,(string)($_POST['password']??''));
        if((int)($user['id']??0)!==$expectedUserId||(string)($user['role_code']??'')!=='customer'){
            role_mfa_logout($pdo,'club_member_identity_mismatch');
            throw new RuntimeException('Club Member sign-in details could not be verified.');
        }
        $_SESSION['hwc_customer_login_mode']='club_member';
        $_SESSION['hwc_verified_member_code']=$memberCode;
        if(!empty($user['mfa_required'])){header('Location: mfa_verify.php');exit;}
        header('Location: '.((int)$user['must_change_password']===1?'change_password.php?required=1':'customer_portal.php'));exit;
    }
}catch(Throwable $e){$error=$e->getMessage();try{security_step17_session_start();$csrf=security_step17_csrf();}catch(Throwable){$csrf='';}}
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Club Member Login - Healthcare Wellness Club</title><link rel="stylesheet" href="pages/auth.css"><style>.member-shell{max-width:1120px;margin:26px auto;padding:0 14px}.member-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.member-hero,.member-card{border:1px solid #dce8e1;border-radius:24px;background:#fff;box-shadow:0 16px 38px rgba(31,65,46,.06)}.member-hero{padding:34px;background:radial-gradient(circle at 90% 8%,rgba(214,170,61,.18),transparent 30%),linear-gradient(135deg,#f7fcf9,#fffaf0)}.member-card{padding:28px}.member-badge{display:inline-flex;padding:7px 10px;border-radius:999px;background:#173f2e;color:#fff;font-size:.65rem;font-weight:900;letter-spacing:.08em}.member-hero h1{font-size:clamp(2.2rem,5vw,4rem);line-height:1;letter-spacing:-.055em;color:#173c2c;margin:16px 0 10px}.member-hero p{color:#65776e;line-height:1.65}.member-points{display:grid;gap:9px;margin-top:20px}.member-point{padding:12px;border:1px solid #dce8e1;border-radius:14px;background:rgba(255,255,255,.82);color:#52685d;font-size:.78rem}.member-card h2{margin:8px 0;color:#173c2c}.member-note{margin-top:14px;padding:12px 14px;border:1px solid #e7ddbd;border-radius:13px;background:#fffaf0;color:#725d2d;font-size:.72rem;line-height:1.6}.member-switch{margin-top:14px;text-align:center;font-size:.78rem}.member-switch a{font-weight:850}@media(max-width:820px){.member-grid{grid-template-columns:1fr}.member-hero{padding:24px}}</style></head><body class="auth-page"><header class="auth-top"><a class="auth-brand" href="index.html"><img src="img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>Verified Club Member Access</small></span></a><nav class="auth-nav"><a class="auth-btn" href="login.php">Regular Login</a><a class="auth-btn" href="shop/index.php">Products</a></nav></header><main class="member-shell"><div class="member-grid"><section class="member-hero"><span class="member-badge">ALREADY A CLUB MEMBER</span><h1>Your verified member pricing follows your account.</h1><p>Use the Club Member ID assigned by the Administrator or your Coach. Your password and optional authenticator verification still protect the account.</p><div class="member-points"><div class="member-point"><b>Member ID</b><br>Confirms which Club Membership profile belongs to your Customer login.</div><div class="member-point"><b>Assigned Discount Label</b><br>Eligible products use the exact stored price level connected to your Bronze, Silver, Gold or other approved label.</div><div class="member-point"><b>Delivery Rule</b><br>For applicable home delivery, below 100 VP adds ₹118; 100 VP or more shows ₹0 delivery charge.</div></div></section><section class="member-card"><div class="auth-kicker">CLUB MEMBER SIGN IN</div><h2>Verify membership and sign in</h2><p>Enter the email, password and Club Member ID connected to the same customer account.</p><?php if($error):?><div class="auth-alert" role="alert"><?=security_step17_h($error)?></div><?php endif;?><form class="auth-form" method="post" autocomplete="on"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><div class="auth-field"><label for="email">Customer Email</label><input class="auth-input" id="email" type="email" name="email" required autocomplete="username" autofocus></div><div class="auth-field"><label for="member_code">Club Member ID</label><input class="auth-input" id="member_code" name="member_code" required maxlength="60" placeholder="HWC-26-XXXXXXXX" autocomplete="off"></div><div class="auth-field"><label for="password">Password</label><div class="password-wrap"><input class="auth-input" id="password" type="password" name="password" required autocomplete="current-password"><button class="password-toggle" id="togglePassword" type="button">Show</button></div></div><button class="auth-submit" type="submit">Sign In as Club Member</button></form><div class="member-note">Club Member ID is not a password and cannot bypass password, MFA, lock or trusted-device controls.</div><div class="member-switch">Not a Club Member? <a href="login.php">Use regular customer login</a></div></section></div></main><script>document.getElementById('togglePassword')?.addEventListener('click',function(){const p=document.getElementById('password');const show=p.type==='password';p.type=show?'text':'password';this.textContent=show?'Hide':'Show'});</script></body></html>
